$lessons[] = ['level' => 'intermediate', 'topic' => 'The Ethics of Genetic Testing', 'background_key' => 'minimal-dark',
    'warmup' => V("Let's talk about genetic testing. Would you want to know your genetic risk for diseases you might develop in the future?", 'Давайте поговорим о генетическом тестировании. Хотели бы вы знать свой генетический риск заболеваний, которые могут развиться в будущем?', 'Генетикалық тестілеу туралы сөйлесейік. Болашақта дамуы мүмкін ауруларға генетикалық тәуекеліңізді білгіңіз келе ме?'),
    'vocab' => [V('genetic testing', 'генетическое тестирование', 'генетикалық тестілеу'), V('predisposition', 'предрасположенность', 'бейімділік'), V('privacy', 'конфиденциальность', 'құпиялылық'), V('discrimination', 'дискриминация', 'кемсіту'), V('insurance company', 'страховая компания', 'сақтандыру компаниясы'), V('DNA', 'ДНК', 'ДНҚ'), V('informed consent', 'информированное согласие', 'хабардар келісім'), V('genetic counseling', 'генетическое консультирование', 'генетикалық кеңес беру'), V('anxiety', 'тревога', 'мазасыздық'), V('data security', 'безопасность данных', 'деректер қауіпсіздігі')],
    'questions' => [
        V('Would you want to know your genetic risk for future diseases?', 'Хотели бы вы знать свой генетический риск будущих заболеваний?', 'Болашақ ауруларға генетикалық тәуекеліңізді білгіңіз келе ме?'),
        V('Do you think insurance companies should have access to genetic test results?', 'Как вы думаете, страховые компании должны иметь доступ к результатам генетических тестов?', 'Сақтандыру компанияларының генетикалық тест нәтижелеріне қолжетімділігі болуы керек пе?'),
        V('Have you or anyone you know taken a consumer DNA test?', 'Вы или кто-то из ваших знакомых проходили потребительский ДНК-тест?', 'Сіз немесе таныстарыңыз тұтынушылық ДНҚ тестінен өттіңіз бе?'),
        V('Do you worry about genetic discrimination in employment or insurance?', 'Вы беспокоитесь о генетической дискриминации при трудоустройстве или страховании?', 'Жұмысқа орналасуда немесе сақтандыруда генетикалық кемсітушілік туралы алаңдайсыз ба?'),
        V('Do you think knowing about a genetic risk could cause unnecessary anxiety?', 'Как вы думаете, знание о генетическом риске может вызвать ненужную тревогу?', 'Генетикалық тәуекел туралы білу қажетсіз мазасыздық тудыруы мүмкін деп ойлайсыз ба?'),
        V('Should genetic counseling be required before receiving test results?', 'Должно ли генетическое консультирование быть обязательным перед получением результатов теста?', 'Тест нәтижелерін алмас бұрын генетикалық кеңес беру міндетті болуы керек пе?'),
        V('Do you trust companies to keep your genetic data secure?', 'Вы доверяете компаниям в защите ваших генетических данных?', 'Компаниялардың генетикалық деректеріңізді қауіпсіз сақтайтынына сенесіз бе?'),
        V('Would you want to know if you carry a gene for a disease with no cure?', 'Вы бы хотели знать, есть ли у вас ген заболевания, от которого нет лечения?', 'Емі жоқ ауру геніне ие екеніңізді білгіңіз келе ме?'),
        V('Do you think parents should be allowed to test embryos for genetic conditions?', 'Как вы думаете, родителям следует разрешать тестировать эмбрионы на генетические состояния?', 'Ата-аналарға эмбриондарды генетикалық жағдайларға тестілеуге рұқсат берілуі керек пе?'),
        V('Should genetic test results be shared with family members who might be affected?', 'Должны ли результаты генетических тестов передаваться членам семьи, которых это может касаться?', 'Генетикалық тест нәтижелері әсер етуі мүмкін отбасы мүшелерімен бөлісілуі керек пе?'),
        V('Do you think genetic testing could lead to a new form of social inequality?', 'Как вы думаете, генетическое тестирование может привести к новой форме социального неравенства?', 'Генетикалық тестілеу жаңа әлеуметтік теңсіздік түріне әкелуі мүмкін деп ойлайсыз ба?'),
        V('Would you make different lifestyle choices based on a genetic risk result?', 'Вы бы сделали другой выбор образа жизни на основе результата генетического риска?', 'Генетикалық тәуекел нәтижесіне негізделіп өмір салтын басқаша таңдар ма едіңіз?'),
        V('Do you think this technology is advancing faster than laws can regulate it?', 'Как вы думаете, эта технология развивается быстрее, чем законы могут её регулировать?', 'Бұл технология заңдар реттей алатыннан жылдамырақ дамиды деп ойлайсыз ба?'),
        V('Do you think genetic privacy should be a fundamental right?', 'Как вы думаете, генетическая конфиденциальность должна быть основным правом?', 'Генетикалық құпиялылық негізгі құқық болуы керек деп ойлайсыз ба?'),
        V('What safeguards would make you more comfortable taking a genetic test?', 'Какие меры защиты сделали бы вас более спокойным при прохождении генетического теста?', 'Генетикалық тест тапсыруда өзіңізді ыңғайлырақ сезінуге қандай қорғаныс шаралары көмектесер еді?'),
    ],
];

$insert = $pdo->prepare('INSERT INTO lessons (teacher_id, level, topic, vocab, warmup, questions, background_key) VALUES (:teacher_id, :level, :topic, :vocab, :warmup, :questions, :background_key)');
$count = 0;
foreach ($lessons as $lesson) {
    $insert->execute([
        ':teacher_id' => $teacherId, ':level' => $lesson['level'], ':topic' => $lesson['topic'],
        ':vocab' => json_encode($lesson['vocab'], JSON_UNESCAPED_UNICODE),
        ':warmup' => json_encode($lesson['warmup'], JSON_UNESCAPED_UNICODE),
        ':questions' => json_encode($lesson['questions'], JSON_UNESCAPED_UNICODE),
        ':background_key' => $lesson['background_key'],
    ]);
    $count++;
}
echo "Inserted $count lessons for teacher '$username' (id $teacherId).\n";
